UPDATE prepaid
SET status = #{status}
WHERE regId = #{regId}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM prepaid
    WHERE userId = #{userId}
      AND UPPER(status) = 'REQUESTED'
)

SELECT EXISTS (
    SELECT 1
    FROM parking_records
    WHERE carNum = #{carNum}
      AND exitTime IS NULL
)
